INSERT INTO `wp_comments` VALUES (1,1,'A WordPress Commenter','wapuu@wordpress.example','https://wordpress.org/','','2026-10-13 07:37:17','2026-10-13 07:37:17','Hi, this is a comment.\nTo get started with moderating, editing, and deleting comments, please visit the Comments screen in the dashboard.\nCommenter avatars come from <a href=\"https://gravatar.com/\">Gravatar</a>.',0,'1','','comment',0,0),(2,31,'WooCommerce','','','','2026-10-29 10:47:39','2026-10-29 10:47:39','Stock hold of 60 minutes applied to: <br>- Basic T-Shirt (TSHIRT-001) &times; 2',0,'1','WooCommerce','order_note',0,0),(3,31,'WooCommerce','','','','2026-10-29 10:47:40','2026-10-29 10:47:40','Stock levels reduced: Basic T-Shirt (20&rarr;18)',0,'1','WooCommerce','order_note',0,0),(4,31,'WooCommerce','','','','2026-10-29 10:47:40','2026-10-29 10:47:40','Payment to be made upon delivery. Order status changed from Pending payment to Processing.',0,'1','WooCommerce','order_note',0,0),(5,31,'WooCommerce','','','','2026-10-29 10:47:40','2026-10-29 10:47:40','Email \"New order\" failed to send: Could not instantiate mail function..',0,'1','WooCommerce','order_note',0,0),(6,31,'WooCommerce','','','','2026-10-29 10:47:40','2026-10-29 10:47:40','Email \"Processing order\" failed to send: Could not instantiate mail function..',0,'1','WooCommerce','order_note',0,0),(7,32,'WooCommerce','','','','2026-10-29 13:26:57','2026-10-29 13:26:57','Email \"Failed order\" failed to send: Could not instantiate mail function..',0,'1','WooCommerce','order_note',0,0),(8,32,'WooCommerce','','','','2026-10-29 13:26:57','2026-10-29 13:26:57','Failed to process the payment. Please try again or contact the shop admin. [UNPROCESSABLE_ENTITY] The requested action could not be performed, semantically incorrect, or failed business validation. https://developer.paypal.com/api/rest/reference/orders/v2/errors/#CURRENCY_NOT_SUPPORTED PayPalGateway.php:477 CURRENCY_NOT_SUPPORTED  Currency code is not currently supported. Please refer https: